insert into public.glossary_terms (slug, term, term_bn, explain_en, explain_bn, source_url, last_verified, is_sample, published, origin) values
  ('ects', 'ECTS', 'ইসিটিএস', 'European credit points. One year of full-time study is 60 ECTS, so a 2-year master''s is usually 120 ECTS.', 'ইউরোপের ক্রেডিট পদ্ধতি। এক বছরের পূর্ণকালীন পড়াশোনা ৬০ ইসিটিএস, তাই ২ বছরের মাস্টার্স সাধারণত ১২০ ইসিটিএস।', 'https://example.org/sample/glossary/ects', '2026-08-24', true, true, 'sample'),
  ('moi', 'MOI (Medium of Instruction letter)', 'এমওআই (মিডিয়াম অব ইনস্ট্রাকশন চিঠি)', 'A letter from your university saying your degree was taught in English. Some programs accept it instead of IELTS.', 'আপনার বিশ্ববিদ্যালয়ের চিঠি, যেখানে বলা থাকে ডিগ্রিটি ইংরেজিতে পড়ানো হয়েছে। কিছু প্রোগ্রাম আইইএলটিএসের বদলে এটি গ্রহণ করে।', 'https://example.org/sample/glossary/moi', '2026-10-28', true, true, 'sample'),
  ('ielts', 'IELTS', 'আইইএলটিএস', 'An English test scored in bands from 0 to 9. Most master''s programs ask for 6.0 to 6.5.', '০ থেকে ৯ ব্যান্ডে নম্বর দেওয়া ইংরেজি পরীক্ষা। বেশিরভাগ মাস্টার্স প্রোগ্রাম ৬.০ থেকে ৬.৫ চায়।', 'https://example.org/sample/glossary/ielts', '2026-10-12', true, true, 'sample'),
  ('cgpa', 'CGPA', 'সিজিপিএ', 'Your cumulative grade point average. In Bangladesh it is usually out of 4.00; universities abroad may convert it to their own scale.', 'আপনার সামগ্রিক গ্রেড পয়েন্ট গড়। বাংলাদেশে সাধারণত ৪.০০-এর মধ্যে; বিদেশের বিশ্ববিদ্যালয় এটি নিজেদের স্কেলে রূপান্তর করতে পারে।', 'https://example.org/sample/glossary/cgpa', '2026-09-20', true, true, 'sample'),
  ('gpa-5', 'SSC/HSC GPA', 'এসএসসি/এইচএসসি জিপিএ', 'Your board exam result out of 5.00. Bachelor''s programs abroad use it for admission.', '৫.০০-এর মধ্যে আপনার বোর্ড পরীক্ষার ফল। বিদেশে ব্যাচেলর ভর্তিতে এটি দেখা হয়।', 'https://example.org/sample/glossary/gpa-5', '2026-08-24', true, true, 'sample'),
  ('three-year-bachelor', '3-year bachelor''s', '৩ বছরের ব্যাচেলর', 'Pass degrees and some programs in Bangladesh take 3 years. Some master''s programs abroad only accept 4-year degrees, so check before applying.', 'বাংলাদেশে পাস কোর্স ও কিছু প্রোগ্রাম ৩ বছরের। বিদেশের কিছু মাস্টার্স শুধু ৪ বছরের ডিগ্রি গ্রহণ করে, তাই আবেদনের আগে দেখে নিন।', 'https://example.org/sample/glossary/three-year-bachelor', '2026-10-28', true, true, 'sample'),
  ('provisional-certificate', 'Provisional certificate', 'প্রভিশনাল সার্টিফিকেট', 'A temporary certificate issued before the final degree certificate. Useful when results are delayed by session jam.', 'মূল সার্টিফিকেটের আগে দেওয়া অস্থায়ী সনদ। সেশনজটে ফল দেরি হলে এটি কাজে লাগে।', 'https://example.org/sample/glossary/provisional-certificate', '2026-10-12', true, true, 'sample'),
  ('session-jam', 'Session jam', 'সেশনজট', 'Delays that push a degree past its normal length. Universities abroad may ask why your study took longer.', 'যে দেরিতে ডিগ্রি স্বাভাবিক সময়ের চেয়ে লম্বা হয়ে যায়। বিদেশের বিশ্ববিদ্যালয় জানতে চাইতে পারে কেন পড়াশোনায় বেশি সময় লেগেছে।', 'https://example.org/sample/glossary/session-jam', '2026-09-20', true, true, 'sample'),
  ('attestation', 'Document attestation', 'কাগজপত্র সত্যায়ন', 'Official confirmation that your certificates are genuine, usually from the education board, ministry and embassy. Start early: it can take weeks.', 'আপনার সনদ আসল কি না তার আনুষ্ঠানিক নিশ্চয়তা, সাধারণত শিক্ষা বোর্ড, মন্ত্রণালয় ও দূতাবাস থেকে। আগে শুরু করুন: কয়েক সপ্তাহ লাগতে পারে।', 'https://example.org/sample/glossary/attestation', '2026-08-24', true, true, 'sample'),
  ('transcript', 'Transcript', 'ট্রান্সক্রিপ্ট', 'The official list of every course and grade in your degree, issued by your university.', 'আপনার ডিগ্রির প্রতিটি কোর্স ও গ্রেডের আনুষ্ঠানিক তালিকা, যা বিশ্ববিদ্যালয় দেয়।', 'https://example.org/sample/glossary/transcript', '2026-10-28', true, true, 'sample'),
  ('motivation-letter', 'Motivation letter', 'মোটিভেশন লেটার', 'A one- or two-page letter explaining why you want this program and how it fits your goals. Write a new one for each program.', 'এক-দুই পাতার চিঠি, যেখানে লিখবেন কেন এই প্রোগ্রাম চান আর এটি আপনার লক্ষ্যের সাথে কীভাবে মেলে। প্রতিটি প্রোগ্রামের জন্য আলাদা লিখুন।', 'https://example.org/sample/glossary/motivation-letter', '2026-10-12', true, true, 'sample'),
  ('lor', 'Letter of recommendation', 'রিকমেন্ডেশন লেটার', 'A letter from a teacher or employer about your abilities. Ask early and give them your CV.', 'আপনার যোগ্যতা নিয়ে শিক্ষক বা নিয়োগকর্তার চিঠি। আগেভাগে অনুরোধ করুন এবং তাঁদের আপনার সিভি দিন।', 'https://example.org/sample/glossary/lor', '2026-09-20', true, true, 'sample'),
  ('intake', 'Intake', 'ইনটেক', 'The month a program starts. Most European programs start in September or October; some also start in February or March.', 'যে মাসে প্রোগ্রাম শুরু হয়। ইউরোপের বেশিরভাগ প্রোগ্রাম সেপ্টেম্বর বা অক্টোবরে শুরু হয়; কিছু ফেব্রুয়ারি বা মার্চেও।', 'https://example.org/sample/glossary/intake', '2026-08-24', true, true, 'sample'),
  ('non-eu-seats', 'Non-EU seats', 'নন-ইইউ আসন', 'Places reserved for applicants from outside the EU, such as Bangladesh. When a university doesn''t publish the number, we show "Not published".', 'ইইউর বাইরের (যেমন বাংলাদেশের) আবেদনকারীদের জন্য সংরক্ষিত আসন। বিশ্ববিদ্যালয় সংখ্যা প্রকাশ না করলে আমরা "প্রকাশিত নয়" দেখাই।', 'https://example.org/sample/glossary/non-eu-seats', '2026-10-28', true, true, 'sample'),
  ('tuition-free', 'Tuition-free', 'টিউশন-ফ্রি', 'No tuition fee, but you still pay living costs and often a small semester fee.', 'টিউশন ফি নেই, তবে জীবনযাত্রার খরচ আর প্রায়ই সামান্য সেমিস্টার ফি দিতে হয়।', 'https://example.org/sample/glossary/tuition-free', '2026-10-12', true, true, 'sample'),
  ('semester-contribution', 'Semester contribution', 'সেমিস্টার কন্ট্রিবিউশন', 'A small fee German students pay each semester, often including a public transport ticket.', 'জার্মানিতে প্রতি সেমিস্টারে দেওয়া ছোট ফি, যাতে প্রায়ই গণপরিবহনের টিকিট থাকে।', 'https://example.org/sample/glossary/semester-contribution', '2026-09-20', true, true, 'sample'),
  ('blocked-account', 'Blocked account', 'ব্লকড অ্যাকাউন্ট', 'A German bank account holding a year of living costs that you can withdraw only monthly. Used as proof of funds for the visa.', 'জার্মান ব্যাংক অ্যাকাউন্ট, যেখানে এক বছরের খরচ জমা থাকে এবং মাসে মাসে তোলা যায়। ভিসার জন্য আর্থিক সামর্থ্যের প্রমাণ হিসেবে লাগে।', 'https://example.org/sample/glossary/blocked-account', '2026-08-24', true, true, 'sample'),
  ('uni-assist', 'uni-assist', 'ইউনি-অ্যাসিস্ট', 'A service many German universities use to check international applications before they decide. It charges a fee per application.', 'অনেক জার্মান বিশ্ববিদ্যালয় সিদ্ধান্তের আগে আন্তর্জাতিক আবেদন যাচাইয়ে এই সেবা ব্যবহার করে। প্রতি আবেদনে ফি লাগে।', 'https://example.org/sample/glossary/uni-assist', '2026-10-28', true, true, 'sample'),
  ('german-grade', 'German grade scale', 'জার্মান গ্রেড স্কেল', 'Germany grades from 1.0 (best) to 4.0 (pass). Universities convert your CGPA with a formula, so a lower German number is better.', 'জার্মানিতে গ্রেড ১.০ (সেরা) থেকে ৪.০ (পাস)। বিশ্ববিদ্যালয় সূত্র দিয়ে আপনার সিজিপিএ রূপান্তর করে, তাই জার্মান সংখ্যা যত কম তত ভালো।', 'https://example.org/sample/glossary/german-grade', '2026-10-12', true, true, 'sample'),
  ('dsu', 'DSU (right-to-study grant)', 'ডিএসইউ (রাইট-টু-স্টাডি গ্রান্ট)', 'Italy''s regional grants based on family income. They can cover tuition, a cash grant, meals and housing.', 'ইতালির আঞ্চলিক অনুদান, যা পরিবারের আয়ের ভিত্তিতে দেওয়া হয়। টিউশন, নগদ অনুদান, খাবার ও থাকার খরচ মেটাতে পারে।', 'https://example.org/sample/glossary/dsu', '2026-09-20', true, true, 'sample'),
  ('residence-permit', 'Residence permit', 'রেসিডেন্স পারমিট', 'Permission to live in the country for your studies. You usually apply soon after arrival, even if you entered with a visa.', 'পড়াশোনার জন্য দেশে থাকার অনুমতি। ভিসায় প্রবেশ করলেও সাধারণত পৌঁছানোর পর দ্রুত আবেদন করতে হয়।', 'https://example.org/sample/glossary/residence-permit', '2026-08-24', true, true, 'sample'),
  ('health-insurance', 'Health insurance', 'স্বাস্থ্যবীমা', 'Required for students in all three countries. Costs differ a lot: check what your city guide shows.', 'তিনটি দেশেই শিক্ষার্থীদের জন্য বাধ্যতামূলক। খরচে অনেক পার্থক্য: আপনার শহরের গাইডে দেখুন।', 'https://example.org/sample/glossary/health-insurance', '2026-10-28', true, true, 'sample'),
  ('conditional-offer', 'Conditional offer', 'শর্তসাপেক্ষ অফার', 'An admission that becomes final once you send a missing item, such as your final certificate or English score.', 'এমন ভর্তি, যা বাকি থাকা কিছু (যেমন চূড়ান্ত সনদ বা ইংরেজি স্কোর) পাঠালে চূড়ান্ত হয়।', 'https://example.org/sample/glossary/conditional-offer', '2026-10-12', true, true, 'sample'),
  ('application-fee', 'Application fee', 'আবেদন ফি', 'A fee paid when you apply, usually by international card or bank transfer from Bangladesh. It is rarely refunded.', 'আবেদনের সময় দেওয়া ফি, সাধারণত বাংলাদেশ থেকে আন্তর্জাতিক কার্ড বা ব্যাংক ট্রান্সফারে। সাধারণত ফেরত দেওয়া হয় না।', 'https://example.org/sample/glossary/application-fee', '2026-09-20', true, true, 'sample'),
  ('student-file', 'Student file', 'স্টুডেন্ট ফাইল', 'A file opened at a Bangladeshi bank so you can legally send tuition and living costs abroad.', 'বাংলাদেশি ব্যাংকে খোলা ফাইল, যাতে বৈধভাবে বিদেশে টিউশন ও জীবনযাত্রার খরচ পাঠাতে পারেন।', 'https://example.org/sample/glossary/student-file', '2026-08-24', true, true, 'sample')
insert into public.countries (slug, name_en, name_bn, currency, eu_member, overview_en, overview_bn, education_system_en, education_system_bn, post_study_work_en, post_study_work_bn, student_work_hours, student_work_note_en, student_work_note_bn, min_wage, min_wage_note_en, min_wage_note_bn, visa_info_en, visa_info_bn, visa_info_url, embassy_url, source_url, last_verified, is_sample, photo, published, origin) values
  ('italy', 'Italy', 'ইতালি', 'EUR', true, 'Italy draws Bangladeshi students with low public tuition that scales with family income, many English-taught master''s programs and regional study grants.', 'পাবলিক বিশ্ববিদ্যালয়ে পরিবারের আয় অনুযায়ী কম টিউশন, ইংরেজিতে পড়ানো অনেক মাস্টার্স প্রোগ্রাম আর আঞ্চলিক স্টাডি গ্রান্টের জন্য ইতালি বাংলাদেশি শিক্ষার্থীদের কাছে জনপ্রিয়।', 'Bachelor''s degrees take 3 years (180 ECTS) and master''s degrees 2 years (120 ECTS). Public universities set fees by income band; private universities charge fixed fees.', 'ব্যাচেলর ৩ বছরের (১৮০ ইসিটিএস) এবং মাস্টার্স ২ বছরের (১২০ ইসিটিএস)। পাবলিক বিশ্ববিদ্যালয় আয় অনুযায়ী ফি ঠিক করে; প্রাইভেট বিশ্ববিদ্যালয়ের ফি নির্দিষ্ট।', 'Graduates can apply to stay up to 12 months to look for work or start a business.', 'পড়া শেষে কাজ খোঁজা বা ব্যবসা শুরুর জন্য সর্বোচ্চ ১২ মাস থাকার আবেদন করা যায়।', 20, 'Up to 20 hours a week during term; full time during breaks.', 'সেমিস্টার চলাকালে সপ্তাহে সর্বোচ্চ ২০ ঘণ্টা; ছুটিতে পূর্ণকালীন।', null, 'No national minimum wage; pay is set by sector agreements.', 'জাতীয় ন্যূনতম মজুরি নেই; খাতভিত্তিক চুক্তিতে বেতন ঠিক হয়।', 'Apply for a long-stay study visa at the embassy once you have an offer, then apply for a residence permit soon after arrival. Check the embassy page for the current document list.', 'অফার পাওয়ার পর দূতাবাসে দীর্ঘমেয়াদি স্টাডি ভিসার আবেদন করুন, পৌঁছে দ্রুত রেসিডেন্স পারমিটের আবেদন করুন। বর্তমান কাগজপত্রের তালিকা দূতাবাসের পেজে দেখুন।', 'https://example.org/sample/visa/italy', 'https://example.org/sample/embassy/italy', 'https://example.org/sample/countries/italy', '2026-10-28', true, '{"src":"/photos/italy.webp","credit":"Pexels","source_url":"https://www.pexels.com/photo/aerial-view-of-florence-with-historic-architecture-31357708/"}'::jsonb, true, 'sample'),
  ('germany', 'Germany', 'জার্মানি', 'EUR', true, 'Germany is known for tuition-free public universities and strong engineering and science programs. Many master''s programs are taught in English, but German helps a lot for jobs.', 'টিউশন-ফ্রি পাবলিক বিশ্ববিদ্যালয় আর শক্তিশালী ইঞ্জিনিয়ারিং ও বিজ্ঞান প্রোগ্রামের জন্য জার্মানি পরিচিত। অনেক মাস্টার্স ইংরেজিতে পড়ানো হয়, তবে চাকরির জন্য জার্মান ভাষা খুব কাজে লাগে।', 'Bachelor''s degrees take 3–4 years and master''s degrees 1.5–2 years. Most public universities charge no tuition, only a semester contribution. Universities of applied sciences focus on practice.', 'ব্যাচেলর ৩–৪ বছরের এবং মাস্টার্স ১.৫–২ বছরের। বেশিরভাগ পাবলিক বিশ্ববিদ্যালয়ে টিউশন নেই, শুধু সেমিস্টার কন্ট্রিবিউশন দিতে হয়। ইউনিভার্সিটি অব অ্যাপ্লাইড সায়েন্সেস ব্যবহারিক শিক্ষায় জোর দেয়।', 'Graduates can stay up to 18 months to look for a job related to their degree.', 'পড়া শেষে ডিগ্রির সাথে মিল আছে এমন চাকরি খুঁজতে সর্বোচ্চ ১৮ মাস থাকা যায়।', 20, 'Up to 20 hours a week during term, or a yearly limit of full days.', 'সেমিস্টার চলাকালে সপ্তাহে সর্বোচ্চ ২০ ঘণ্টা, অথবা বছরে নির্দিষ্ট সংখ্যক পূর্ণ দিন।', 13.5, 'Gross hourly minimum wage (sample figure).', 'ঘণ্টাপ্রতি ন্যূনতম মজুরি (নমুনা সংখ্যা)।', 'Apply for a national study visa at the embassy with your admission letter and proof of funds, often a blocked account. Appointment waiting times can be long, so book early.', 'ভর্তির চিঠি আর আর্থিক সামর্থ্যের প্রমাণ (প্রায়ই ব্লকড অ্যাকাউন্ট) নিয়ে দূতাবাসে ন্যাশনাল স্টাডি ভিসার আবেদন করুন। অ্যাপয়েন্টমেন্ট পেতে দেরি হতে পারে, তাই আগে বুক করুন।', 'https://example.org/sample/visa/germany', 'https://example.org/sample/embassy/germany', 'https://example.org/sample/countries/germany', '2026-10-12', true, '{"src":"/photos/germany.webp","credit":"Pexels","source_url":"https://www.pexels.com/photo/sommerabend-am-rhein-27831541/"}'::jsonb, true, 'sample'),
  ('hungary', 'Hungary', 'হাঙ্গেরি', 'HUF', true, 'Hungary offers affordable English-taught programs, lower living costs than Western Europe and a government scholarship that is open to Bangladeshi students.', 'হাঙ্গেরিতে ইংরেজিতে পড়ানো সাশ্রয়ী প্রোগ্রাম, পশ্চিম ইউরোপের চেয়ে কম জীবনযাত্রার খরচ আর বাংলাদেশি শিক্ষার্থীদের জন্য খোলা সরকারি স্কলারশিপ আছে।', 'Bachelor''s degrees take 3–4 years and master''s degrees 2 years. Public universities charge international students tuition, usually in euros.', 'ব্যাচেলর ৩–৪ বছরের এবং মাস্টার্স ২ বছরের। পাবলিক বিশ্ববিদ্যালয় আন্তর্জাতিক শিক্ষার্থীদের কাছ থেকে সাধারণত ইউরোতে টিউশন নেয়।', 'Graduates can apply to stay up to 9 months to look for work.', 'পড়া শেষে কাজ খুঁজতে সর্বোচ্চ ৯ মাস থাকার আবেদন করা যায়।', 24, 'Up to 24 hours a week during term; full time during breaks.', 'সেমিস্টার চলাকালে সপ্তাহে সর্বোচ্চ ২৪ ঘণ্টা; ছুটিতে পূর্ণকালীন।', 1600, 'Gross hourly minimum wage in forint (sample figure).', 'ফোরিন্টে ঘণ্টাপ্রতি ন্যূনতম মজুরি (নমুনা সংখ্যা)।', 'Apply for a residence permit for study purposes with your acceptance letter, accommodation and proof of funds. Check the embassy page for where Bangladeshi applicants submit.', 'ভর্তির চিঠি, থাকার ব্যবস্থা আর আর্থিক সামর্থ্যের প্রমাণ নিয়ে পড়াশোনার রেসিডেন্স পারমিটের আবেদন করুন। বাংলাদেশি আবেদনকারীরা কোথায় জমা দেবেন তা দূতাবাসের পেজে দেখুন।', 'https://example.org/sample/visa/hungary', 'https://example.org/sample/embassy/hungary', 'https://example.org/sample/countries/hungary', '2026-09-20', true, '{"src":"/photos/hungary.webp","credit":"Pexels","source_url":"https://www.pexels.com/photo/scenic-view-of-esztergom-by-the-danube-river-38440205/"}'::jsonb, true, 'sample')
insert into public.cities (slug, name_en, name_bn, country, overview_en, overview_bn, population_students, local_language_needed_for_jobs, local_language_note_en, local_language_note_bn, bd_community_note_en, bd_community_note_bn, cost_rent_shared, cost_rent_studio, cost_food, cost_transport, cost_phone, cost_insurance, common_student_jobs, job_search_links, source_url, last_verified, is_sample, photo, published, origin) values
  ('milan', 'Milan', 'মিলান', 'italy', 'Italy''s business and design capital, with big universities, a busy job market and the highest rents in the country.', 'ইতালির ব্যবসা ও ডিজাইনের কেন্দ্র; বড় বিশ্ববিদ্যালয়, ব্যস্ত চাকরির বাজার আর দেশের সবচেয়ে বেশি বাসাভাড়া।', 210000, 'essential', 'Most part-time jobs need basic Italian; English-only jobs are rare outside tech.', 'বেশিরভাগ পার্টটাইম কাজে প্রাথমিক ইতালিয়ান লাগে; টেক ছাড়া শুধু ইংরেজিতে কাজ কম।', 'A large Bangladeshi community, with grocery shops and student groups that help newcomers find rooms.', 'বড় বাংলাদেশি কমিউনিটি; দেশি মুদি দোকান আর শিক্ষার্থী গ্রুপ নতুনদের রুম খুঁজতে সাহায্য করে।', 600, 1100, 280, 30, 12, 15, '[{"en":"Restaurant and café staff","bn":"রেস্টুরেন্ট ও ক্যাফে কর্মী"},{"en":"Food delivery","bn":"খাবার ডেলিভারি"},{"en":"Retail assistant","bn":"দোকানের সহকারী"},{"en":"University help desk","bn":"বিশ্ববিদ্যালয়ের হেল্প ডেস্ক"}]'::jsonb, '[{"label":"Sample job board","url":"https://example.org/sample/jobs/milan"},{"label":"Sample student jobs","url":"https://example.org/sample/student-jobs/milan"}]'::jsonb, 'https://example.org/sample/cities/milan', '2026-08-24', true, '{"src":"/photos/milan.webp","credit":"Pexels","source_url":"https://www.pexels.com/photo/majestic-milan-cathedral-under-clear-blue-sky-32721581/"}'::jsonb, true, 'sample'),
  ('bologna', 'Bologna', 'বোলোনিয়া', 'italy', 'A historic university city where students make up a large share of residents; cheaper than Milan but rooms go fast.', 'ঐতিহাসিক বিশ্ববিদ্যালয় শহর, যেখানে বাসিন্দাদের বড় অংশই শিক্ষার্থী; মিলানের চেয়ে সস্তা, তবে রুম দ্রুত ফুরিয়ে যায়।', 90000, 'essential', 'Italian is needed for almost all local jobs.', 'প্রায় সব স্থানীয় কাজে ইতালিয়ান লাগে।', 'A small but active Bangladeshi student group; the nearest large community is in other cities in the region.', 'ছোট কিন্তু সক্রিয় বাংলাদেশি শিক্ষার্থী গ্রুপ; বড় কমিউনিটি অঞ্চলের অন্য শহরে।', 450, 800, 250, 25, 12, 15, '[{"en":"Restaurant and café staff","bn":"রেস্টুরেন্ট ও ক্যাফে কর্মী"},{"en":"Food delivery","bn":"খাবার ডেলিভারি"},{"en":"Library assistant","bn":"লাইব্রেরি সহকারী"}]'::jsonb, '[{"label":"Sample job board","url":"https://example.org/sample/jobs/bologna"},{"label":"Sample student jobs","url":"https://example.org/sample/student-jobs/bologna"}]'::jsonb, 'https://example.org/sample/cities/bologna', '2026-10-28', true, '{"src":"/photos/bologna.webp","credit":"Pexels","source_url":"https://www.pexels.com/photo/stunning-aerial-view-of-bologna-italy-at-dusk-36799900/"}'::jsonb, true, 'sample'),
  ('berlin', 'Berlin', 'বার্লিন', 'germany', 'Germany''s capital and start-up hub, with many English-speaking workplaces and a tight housing market.', 'জার্মানির রাজধানী ও স্টার্টআপ কেন্দ্র; ইংরেজিতে কাজের সুযোগ অনেক, তবে বাসা পাওয়া কঠিন।', 200000, 'helpful', 'English works in tech and start-ups; German opens most other part-time jobs.', 'টেক ও স্টার্টআপে ইংরেজিতে চলে; অন্যান্য বেশিরভাগ পার্টটাইম কাজে জার্মান লাগে।', 'A growing Bangladeshi community, with student associations and community events.', 'বাড়তে থাকা বাংলাদেশি কমিউনিটি; শিক্ষার্থী সংগঠন ও কমিউনিটি অনুষ্ঠান আছে।', 550, 900, 250, 29, 15, 125, '[{"en":"Working student in tech","bn":"টেক কোম্পানিতে ওয়ার্কিং স্টুডেন্ট"},{"en":"Café and restaurant staff","bn":"ক্যাফে ও রেস্টুরেন্ট কর্মী"},{"en":"Delivery rider","bn":"ডেলিভারি রাইডার"},{"en":"Research assistant","bn":"রিসার্চ অ্যাসিস্ট্যান্ট"}]'::jsonb, '[{"label":"Sample job board","url":"https://example.org/sample/jobs/berlin"},{"label":"Sample student jobs","url":"https://example.org/sample/student-jobs/berlin"}]'::jsonb, 'https://example.org/sample/cities/berlin', '2026-10-12', true, '{"src":"/photos/berlin.webp","credit":"Pexels","source_url":"https://www.pexels.com/photo/brandenburg-gate-in-summer-berlin-germany-37468367/"}'::jsonb, true, 'sample'),
  ('munich', 'Munich', 'মিউনিখ', 'germany', 'A wealthy city with strong engineering, automotive and finance employers, and the most expensive rents in Germany.', 'ইঞ্জিনিয়ারিং, গাড়ি শিল্প ও ফিন্যান্সের বড় প্রতিষ্ঠানে ভরা ধনী শহর; জার্মানির সবচেয়ে বেশি বাসাভাড়া।', 130000, 'helpful', 'Large companies hire English speakers as working students; shops and services expect German.', 'বড় কোম্পানি ইংরেজিভাষী ওয়ার্কিং স্টুডেন্ট নেয়; দোকান ও সেবাখাতে জার্মান লাগে।', 'A smaller Bangladeshi community, mostly students and engineers.', 'ছোট বাংলাদেশি কমিউনিটি, বেশিরভাগই শিক্ষার্থী ও ইঞ্জিনিয়ার।', 700, 1200, 280, 29, 15, 125, '[{"en":"Working student in engineering","bn":"ইঞ্জিনিয়ারিংয়ে ওয়ার্কিং স্টুডেন্ট"},{"en":"Event staff","bn":"ইভেন্ট কর্মী"},{"en":"Warehouse and logistics","bn":"গুদাম ও লজিস্টিকস"}]'::jsonb, '[{"label":"Sample job board","url":"https://example.org/sample/jobs/munich"},{"label":"Sample student jobs","url":"https://example.org/sample/student-jobs/munich"}]'::jsonb, 'https://example.org/sample/cities/munich', '2026-09-20', true, '{"src":"/photos/munich.webp","credit":"Pexels","source_url":"https://www.pexels.com/photo/munich-27721888/"}'::jsonb, true, 'sample'),
  ('budapest', 'Budapest', 'বুদাপেস্ট', 'hungary', 'Hungary''s capital, with many international students, good public transport and living costs well below Western Europe.', 'হাঙ্গেরির রাজধানী; অনেক আন্তর্জাতিক শিক্ষার্থী, ভালো গণপরিবহন আর পশ্চিম ইউরোপের চেয়ে অনেক কম খরচ।', 150000, 'helpful', 'Service centres and some start-ups hire in English; most local jobs need Hungarian.', 'সার্ভিস সেন্টার ও কিছু স্টার্টআপ ইংরেজিতে নিয়োগ দেয়; বেশিরভাগ স্থানীয় কাজে হাঙ্গেরিয়ান লাগে।', 'A mid-sized Bangladeshi student community, many on government scholarships.', 'মাঝারি আকারের বাংলাদেশি শিক্ষার্থী কমিউনিটি, অনেকে সরকারি স্কলারশিপে পড়েন।', 160000, 260000, 90000, 3500, 5000, 15000, '[{"en":"Customer service in English","bn":"ইংরেজিতে কাস্টমার সার্ভিস"},{"en":"Food delivery","bn":"খাবার ডেলিভারি"},{"en":"Hostel reception","bn":"হোস্টেল রিসেপশন"}]'::jsonb, '[{"label":"Sample job board","url":"https://example.org/sample/jobs/budapest"},{"label":"Sample student jobs","url":"https://example.org/sample/student-jobs/budapest"}]'::jsonb, 'https://example.org/sample/cities/budapest', '2026-08-24', true, '{"src":"/photos/budapest.webp","credit":"Pexels","source_url":"https://www.pexels.com/photo/parliament-building-in-budapest-18815996/"}'::jsonb, true, 'sample'),
  ('debrecen', 'Debrecen', 'ডেব্রেচেন', 'hungary', 'Hungary''s second-largest city, a calm and cheap university town known for medical and health programs.', 'হাঙ্গেরির দ্বিতীয় বৃহত্তম শহর; শান্ত, সস্তা বিশ্ববিদ্যালয় শহর, চিকিৎসা ও স্বাস্থ্য প্রোগ্রামের জন্য পরিচিত।', 30000, 'essential', 'Part-time jobs in English are scarce; plan your budget without them.', 'ইংরেজিতে পার্টটাইম কাজ খুব কম; এসব কাজ ধরে না নিয়েই বাজেট করুন।', 'A small Bangladeshi student community.', 'ছোট বাংলাদেশি শিক্ষার্থী কমিউনিটি।', 110000, 180000, 80000, 3000, 5000, 15000, '[{"en":"Campus jobs","bn":"ক্যাম্পাসে কাজ"},{"en":"Tutoring","bn":"টিউশন"},{"en":"Food delivery","bn":"খাবার ডেলিভারি"}]'::jsonb, '[{"label":"Sample job board","url":"https://example.org/sample/jobs/debrecen"},{"label":"Sample student jobs","url":"https://example.org/sample/student-jobs/debrecen"}]'::jsonb, 'https://example.org/sample/cities/debrecen', '2026-10-28', true, '{"src":"/photos/debrecen.webp","credit":"Pexels","source_url":"https://www.pexels.com/photo/festive-night-scene-at-debrecen-reformed-church-35441101/"}'::jsonb, true, 'sample')
