insert into public.programs (slug, title, university, degree_level, field, language, duration_months, ects_credits, currency, tuition_per_year, other_fees_per_year, application_fee, intakes, seats_total, seats_non_eu, min_gpa_requirement, accepts_3yr_bachelor, accepts_moi, accepts_provisional, open_to_bd_citizens, english_tests, required_documents, related_bachelor_fields, overview_en, overview_bn, career_paths_en, career_paths_bn, official_url, source_url, last_verified, is_sample, language_requirement_en, language_requirement_bn, published, origin) values
  ('sum-msc-computer-science', 'M.Sc. Computer Science', 'sample-university-of-milan', 'master', 'cse', 'en', 24, 120, 'EUR', 2800, 0, 30, '[{"month":9,"year":2027,"deadline":"2027-03-31"}]'::jsonb, 120, 40, '{"value":3,"scale":4}'::jsonb, true, true, true, true, '[{"test":"ielts","min_score":6},{"test":"toefl_ibt","min_score":80},{"test":"pte","min_score":50},{"test":"duolingo","min_score":105}]'::jsonb, array['passport', 'transcript', 'degree_certificate', 'cv', 'motivation_letter', 'english_certificate', 'moi_letter']::text[], array['cse', 'data-science', 'eee', 'math-physics']::text[], 'M.Sc. Computer Science at Sample University of Milan is a 2-year master''s program taught in English. Core courses cover algorithms, distributed systems, machine learning and software engineering. It ends with a master''s thesis, and a 3-month internship is optional.', 'এটি ২৪ মাসের কম্পিউটার সায়েন্স মাস্টার্স, ইংরেজিতে পড়ানো হয়। মূল কোর্সে অ্যালগরিদম, ডিস্ট্রিবিউটেড সিস্টেম, মেশিন লার্নিং ও সফটওয়্যার ইঞ্জিনিয়ারিং আছে। শেষে থিসিস, আর ৩ মাসের ইন্টার্নশিপ ঐচ্ছিক।', array['Software engineer', 'Machine learning engineer', 'Cloud engineer']::text[], array['সফটওয়্যার ইঞ্জিনিয়ার', 'মেশিন লার্নিং ইঞ্জিনিয়ার', 'ক্লাউড ইঞ্জিনিয়ার']::text[], 'https://example.org/sample/programs/sum-msc-computer-science', 'https://example.org/sample/programs/sum-msc-computer-science', '2026-10-12', true, null, null, true, 'sample'),
  ('sum-msc-data-science-and-economics', 'M.Sc. Data Science and Economics', 'sample-university-of-milan', 'master', 'data-science', 'en', 24, 120, 'EUR', 2800, 0, 30, '[{"month":2,"year":2027,"deadline":"2026-10-15"},{"month":9,"year":2027,"deadline":"2027-02-28"}]'::jsonb, 60, null, '{"value":3,"scale":4}'::jsonb, true, true, false, true, '[{"test":"ielts","min_score":6},{"test":"toefl_ibt","min_score":80},{"test":"pte","min_score":50},{"test":"duolingo","min_score":105}]'::jsonb, array['passport', 'transcript', 'degree_certificate', 'cv', 'motivation_letter', 'english_certificate', 'moi_letter']::text[], array['data-science', 'cse', 'economics', 'math-physics', 'finance']::text[], 'M.Sc. Data Science and Economics at Sample University of Milan is a 2-year master''s program taught in English. Core courses cover statistics, machine learning, data engineering and data ethics. Students can take a part-time track over three years.', null, array['Data scientist', 'Data analyst', 'Data engineer']::text[], array['ডেটা সায়েন্টিস্ট', 'ডেটা অ্যানালিস্ট', 'ডেটা ইঞ্জিনিয়ার']::text[], 'https://example.org/sample/programs/sum-msc-data-science-and-economics', 'https://example.org/sample/programs/sum-msc-data-science-and-economics', '2026-09-20', true, null, null, true, 'sample'),
